import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        sc.close();

        // Precisamos de um inteiro k >= 0 tal que:
        //   A <= C - k*D <= B
        // equivalentemente:
        //   C - B <= k*D <= C - A
        long low = (long) c - b;   // menor valor aceitável para k*D
        long high = (long) c - a;  // maior valor aceitável para k*D

        // Maior múltiplo de D que não excede 'high'
        long maxMultiple = (high / d) * d;

        // Se esse múltiplo alcança o intervalo [low, high], existe solução
        System.out.println(maxMultiple >= low ? "S" : "N");
    }
}
